head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.MGS_NO_UPDT = "저장할 수정내용이 없습니다.";
scwin.MSG_NO_COMT = "위원회심사결과 내역이 없습니다. 새로 추가하시겠습니까?";
scwin.strKeyIsurCd = "";
scwin.gBzProcsNo = "";
scwin.gIsurCd = "";
scwin.gComNm = "";
/************************************************************************************
 * ID           :	ULDSTF005010_SKT
 * File           :	ULDSTF005010_SKT.xml
 * Name         :	[위원회결과 팝업] 위원회결과 내역 조회
 * Author       :	yoo
 * Description  :	[위원회결과 팝업] 위원회결과 내역 조회
 * Create Date  :	2026-07-30
 ************************************************************************************/

scwin.strKeyLstBzProcsNo = ""

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — searchCode, search 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.gBzProcsNo = $c.data.getParameter("gBzProcsNo");
        scwin.gIsurCd = $c.data.getParameter("gIsurCd");
        scwin.gComNm  = $c.data.getParameter("gComNm");

        ibx_IsurCd.setValue(scwin.gIsurCd);
        ibx_CoNm.setValue(scwin.gComNm);

        img_Delete.hide();
        img_Regist.hide();
        img_Save.hide();

        await scwin.searchCode();

        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05010_STK.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {

};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Cmt_OnLoadCompleted
 * @description dts_Cmt 로드 완료 후처리(레거시 Gauce 이벤트 — 순차 스타일에서는 await 뒤에서 호출)
 * @param {*} rowcount rowcount
 * @returns {void}
 * @hidden N
 */
scwin.dts_Cmt_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_Cmt.CountRow > 0) {
            scwin.setKeyCtrOnUpd(); // 조회직후에는 수정상태
            scwin.searchReqInf();
        } else {
            // confirm: 반환값을 동기 boolean 으로 소비하는 위치 — $c.win.confirm 은 Promise 라 1:1 치환 불가(컨벤션 예외, 전환 시 async 재설계 필요)
            if (confirm(scwin.MSG_NO_COMT)) {
                scwin.addNewCmt();
            } else {

                $c.win.closePopup(); // CloseFrame은 호출자가 있을경우 유효하다.
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05010_STK.dts_Cmt_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Cmt_OnRowPosChanged
 * @description dts_Cmt 행 위치 변경 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_Cmt_OnRowPosChanged = function(row) {
    try {
        if (dts_Cmt.CountRow > 0) {

            if (dts_Cmt.NameString(row, "BZ_PROCS_NO") !== "") {
                scwin.searchReqInf();
            }

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05010_STK.dts_Cmt_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name dts_ReqInf_OnLoadCompleted
 * @description dts_ReqInf 로드 완료 후처리(레거시 Gauce 이벤트 — 순차 스타일에서는 await 뒤에서 호출)
 * @param {*} rowcount rowcount
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReqInf_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name tr_Save_OnFail
 * @description tr_Save 트랜잭션 실패 콜백(레거시 Gauce)
 * @returns {void}
 * @hidden N
 */
scwin.tr_Save_OnFail = function() {
    try {
        $c.win.alert(scwin.MSG_TR_FAIL);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05010_STK.tr_Save_OnFail" });
    }
};

/**
 * @method
 * @name tr_Save_OnSuccess
 * @description tr_Save 트랜잭션 성공 콜백(레거시 Gauce)
 * @returns {void}
 * @hidden N
 */
scwin.tr_Save_OnSuccess = function() {
    try {
        $c.win.alert(scwin.MSG_TR_DOME);
        scwin.search();

        // 상장위원회일, 심사구분 reLoad

        const parentWin = $c.win.getParent();

        parentWin.fn_read_sync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05010_STK.tr_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name img_SetComiteDd_onclick
 * @description img_SetComiteDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SetComiteDd_onclick = function() {
    try {
        scwin.showCalendar(ica_ComiteDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05010_STK.img_SetComiteDd_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function() {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05010_STK.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Save_onclick
 * @description 「저장」 버튼 클릭
 * @returns {void}
 * @hidden N
 */
scwin.img_Save_onclick = function() {
    try {
        scwin.save("I");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05010_STK.img_Save_onclick" });
    }
};

/**
 * @method
 * @name img_Regist_onclick
 * @description 「신규」 버튼 클릭
 * @returns {void}
 * @hidden N
 */
scwin.img_Regist_onclick = function() {
    try {
        scwin.addNewCmt();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05010_STK.img_Regist_onclick" });
    }
};

/**
 * @method
 * @name img_Delete_onclick
 * @description 「삭제」 버튼 클릭
 * @returns {void}
 * @hidden N
 */
scwin.img_Delete_onclick = function() {
    try {
        scwin.deleteRow();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05010_STK.img_Delete_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description 코드 목록을 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    // var arrCid = [{
    //     cid: "COMITE_INVSTG_RSLT_CD",
    //     cnm: "sbx_ComiteInvstgRsltCd"
    // }];
    // var objCod;
    const sbmOptions3 = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // var strCbd = "",
    //     i, j;
    // for (i = 0; i < com.wconv.length(arrCid); i++) {

    //     objCod = document.getElementById(arrCid[i].cnm);
    //     if (objCod == null) {
    //         $c.win.alert(arrCid[i].cnm);
    //     }
    //     strCbd = "";
    //     for (j = 1; j <= dts_Cod.CountRow; j++) {

    //         if (dts_Cod.NameString(j, "CD_ENG_NM") == arrCid[i].cid) {

    //             strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.NameString(j, "VALUE") + "^" + com.wconv.replace(/,/g, "','");
    //         }
    //     }
    //     objCod.CBData = strCbd;
    // }
    let param = dma_searchCdReq.getJSON()
    param.codeList = ["COMITE_INVSTG_RSLT_CD"];

    const sbmOptions = {
        id : "sbm_codeList",
        action : "/api/listing/common/code/list-code-value",
        method : "get",
        target : "dlt_selBoxList1=body.COMITE_INVSTG_RSLT_CD",
        isProcessMsg : false
    };

    const res =  await $c.sbm.executeDynamic(sbmOptions,param);
    if (res.responseJSON.success === true) {
            sbx_ComiteInvstgRsltCd.setNodeSet("data:" + "dlt_selBoxList1","text","value");
    }
};

/**
 * @method
 * @name searchReqInf
 * @description 저장자 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchReqInf = async function() {

    const sbmOptions3 = {
        id : "sbm_dts_ReqInf",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ReqInf=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const param = {"bzProcsNo": scwin.gBzProcsNo};

    const sbmOptions = {
        id : "sbm_saveByList",
        action : "/api/listing/lstproc/stock/prelisting-kospi-comite/select-info",
        method : "get",
        target : "dnma_saveByList=body",
        isProcessMsg : true
    };

    const res = await $c.sbm.executeDynamic(sbmOptions, param);
    if(res.responseJSON.success) {
        ibx_BillSubmitDd.setValue(res.responseJSON.body.billSubmitDd);
        ibx_LstComiteRsltSaveEmpNm.setValue(res.responseJSON.body.lstComiteRsltSaveEmpNm)
    }

};

/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 발행기관코드가 키값이다.
    const sbmOptions3 = {
        id : "sbm_dts_Cmt",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Cmt=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.gIsurCd = "12926"; // 임시

    const param = {"isurCd": scwin.gIsurCd};
    const sbmOptions = {
        id : "sbm_prelistingKospiComite",
        action : "/api/listing/lstproc/stock/prelisting-kospi-comite/select-list",
        method : "get",
        target : "dlt_prelistingKospiComit=body",
        isProcessMsg : true
    };

    const res = await $c.sbm.executeDynamic(sbmOptions, param);

    if(res.responseJSON.body.length > 0) {
        rdo_RetrYn.setValue(res.responseJSON.body[0].retrYn);
        ica_ComiteDd.setValue(res.responseJSON.body[0].comiteDd);
        txa_Remk.setValue(res.responseJSON.body[0].remk);
        sbx_ComiteInvstgRsltCd.setValue(res.responseJSON.body[0].comiteInvstgRsltCd)

        await scwin.searchReqInf();
    } else {
        $c.win.alert("위원회심사결과 내역이 없습니다.");
    }

};

/**
 * @method
 * @name save
 * @description 입력값을 저장한다.
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function(jobType) {
    if (js_dep_cd.substring(0, 2) !== '25' && // 유가 - 상장부
        js_dep_cd !== '2615') {
        // 기업심사팀(2615) by nhkw
        $c.win.alert("해당 부서만 접수가 가능합니다.");
        return;
    }

    // if(jobType == "D"){}  -- 삭제일 경우, 쿼리문도 수정해줘야 함.
    // else{

    // 위원회일/철회일 필수 체크
    // 1줄만 있을 경우, 삭제할 수 없음
    if (ica_ComiteDd.getValue() === "") {
        $c.win.alert("위원회일/철회일을 입력하여 주세요");

        ica_ComiteDd.Focus();
        return false;
    }
    // }

    let vScrenProcTpCd;
    if (jobType === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (jobType === "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (jobType === "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    if (dts_Cmt.IsUpdated || dts_ReqInf.IsUpdated) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        /*ORG SRC: dts_ReqInf.NameString(1, "LST_COMITE_RSLT_SAVE_EMP_NO") = fn_getUserId();*/
        X = scwin.getUserId();
        tr_Save.KeyName = "toinb_dataid4";

        const sbmOptions = {
            id : "sbm_tr_Save",
            action : "/Prelisting.do",
            ref : "dts_ReqInf,dts_Cmt",
            target : "tr_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } else {
        $c.win.alert(scwin.MGS_NO_UPDT);
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getUserId
 * @description 로그인 사용자 ID 를 반환한다.
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getUserId = function() {
    return js_emp_no;
};

/**
 * @method
 * @name showCalendar
 * @description 달력 팝업을 표시한다.
 * @param {*} o o
 * @returns {void}
 * @hidden N
 */
scwin.showCalendar = function(o) {
    if ((o !== undefined) && (!o.readOnly)) {

        popUpCalendar2(o);
    }
};

/**
 * @method
 * @name addNewCmt
 * @description 새 위원회 결과 행을 추가한다.
 * @returns {void}
 * @hidden N
 */
scwin.addNewCmt = function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

    dts_Cmt.insertRow(); /*ORG SRC: dts_Cmt.NameValue(dts_Cmt.RowPosition, "BZ_PROCS_NO") = strKeyLstBzProcsNo;*/ X = scwin.strKeyLstBzProcsNo;
    scwin.searchReqInf();
    scwin.setKeyCtrOnAdd(); // 추가상태에서는  key컬럼수정가능
};

/**
 * @method
 * @name deleteRow
 * @description 선택 행을 삭제한다.
 * @returns {void}
 * @hidden N
 */
scwin.deleteRow = function() {
    dts_Cmt.DeleteRow(dts_Cmt.RowPosition);
    scwin.save("D");
};

/**
 * @method
 * @name setKeyCtrOnAdd
 * @description 행 추가 시 키 컬럼 편집 가능 상태를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setKeyCtrOnAdd = function() {

    fn_setCtrWritable([ica_ComiteDd]);
};

/**
 * @method
 * @name setKeyCtrOnUpd
 * @description 행 수정 시 키 컬럼 편집 가능 상태를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setKeyCtrOnUpd = function() {

    fn_setCtrReadOnly([ica_ComiteDd]);
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    const arr = new Array();

    scwin.fn_GetPar = $c.win.getParent().scwin.fn_GetPar;

    scwin.fn_SetPar = $c.win.getParent().scwin.fn_SetPar;

    if (scwin.fn_GetPar !== undefined) {

        scwin.fn_GetPar(arr);
    }
    ibx_IsurCd.setValue((com.wconv.length(arr) >= 1 ? arr[0] : ""));
    scwin.strKeyIsurCd = (com.wconv.length(arr) >= 1 ? arr[0] : "");
    scwin.strKeyLstBzProcsNo = (com.wconv.length(arr) >= 2 ? arr[1] : "");
    ibx_CoNm.setValue((com.wconv.length(arr) >= 3 ? arr[2] : "")); // 발행기관명도 넘겨받아 컨트롤에 반영해야 한다.

    if (com.wconv.length(arr) > 2) {
        scwin.search();
    }
};
